class WaveletTree:
    def __init__(self, arr, low, high):
        self.low = low
        self.high = high
        if low == high or not arr:
            return
        mid = (low + high) // 2
        self.b = [0] * len(arr)
        left = []
        right = []
        for i, val in enumerate(arr):
            self.b[i] = (val <= mid)
            if val <= mid:
                left.append(val)
            else:
                right.append(val)
        self.left_child = WaveletTree(left, low, mid) if left else None
        self.right_child = WaveletTree(right, mid + 1, high) if right else None
    def rank_less_equal(self, idx, k):
        if self.low == self.high:
            return idx + 1 if self.low <= k else 0
        if k <= (self.low + self.high) // 2:
            return self.left_child.rank_less_equal(sum(self.b[:idx+1]) - 1, k) if self.left_child else 0
        else:
            left_count = sum(self.b[:idx+1])
            right_count = (idx + 1) - left_count
            return left_count + (self.right_child.rank_less_equal(right_count - 1, k) if self.right_child else 0)
