class DisjointSparseTable:
    def __init__(self, arr):
        self.n = len(arr)
        self.table = [arr[:]]
        k = 1
        while (1 << k) <= self.n:
            prev = self.table[-1]
            curr = [0] * self.n
            step = 1 << k
            for i in range(step - 1, self.n, step):
                curr[i] = prev[i]
                for j in range(i - 1, i - step, -1):
                    curr[j] = min(prev[j], curr[j + 1])
                if i + 1 < self.n:
                    curr[i + 1] = prev[i + 1]
                    for j in range(i + 2, min(i + step + 1, self.n)):
                        curr[j] = min(prev[j], curr[j - 1])
            self.table.append(curr)
            k += 1
    def query(self, l, r):
        if l == r:
            return self.table[0][l]
        k = (r - l).bit_length() - 1
        return min(self.table[k + 1][l + (1 << k) - 1], self.table[k + 1][r - (1 << k) + 1])
