class CentroidDecomposition:
    def __init__(self, n):
        self.n = n
        self.adj = [[] for _ in range(n)]
        self.size = [0] * n
        self.removed = [False] * n
    def get_size(self, v, p):
        self.size[v] = 1
        for u in self.adj[v]:
            if u != p and not self.removed[u]:
                self.get_size(u, v)
                self.size[v] += self.size[u]
    def get_centroid(self, v, p, total):
        for u in self.adj[v]:
            if u != p and not self.removed[u] and self.size[u] > total // 2:
                return self.get_centroid(u, v, total)
        return v
