class XFastTrie:
    def __init__(self, u):
        self.u = u
        self.w = u.bit_length() - 1
        self.levels = [{} for _ in range(self.w + 1)]
    def insert(self, x):
        for i in range(self.w + 1):
            prefix = x >> (self.w - i) if i > 0 else 0
            if prefix not in self.levels[i]:
                self.levels[i][prefix] = set()
            self.levels[i][prefix].add(x)
    def predecessor(self, x):
        lo, hi = 0, self.w
        while lo < hi:
            mid = (lo + hi + 1) // 2
            prefix = x >> (self.w - mid) if mid > 0 else 0
            if prefix in self.levels[mid]:
                lo = mid
            else:
                hi = mid - 1
        if lo == 0:
            return None
        prefix = x >> (self.w - lo) if lo > 0 else 0
        candidates = self.levels[lo][prefix]
        return max(c for c in candidates if c <= x)
