class HopcroftKarp:
    def __init__(self, left_size, right_size):
        self.n_left = left_size
        self.n_right = right_size
        self.adj = [[] for _ in range(left_size)]
        self.pair_u = [-1] * left_size
        self.pair_v = [-1] * right_size
        self.dist = [0] * left_size
    def bfs(self):
        from collections import deque
        q = deque()
        for u in range(self.n_left):
            if self.pair_u[u] == -1:
                self.dist[u] = 0
                q.append(u)
            else:
                self.dist[u] = float('inf')
        found = False
        while q:
            u = q.popleft()
            for v in self.adj[u]:
                if self.pair_v[v] != -1 and self.dist[self.pair_v[v]] == float('inf'):
                    self.dist[self.pair_v[v]] = self.dist[u] + 1
                    q.append(self.pair_v[v])
                elif self.pair_v[v] == -1:
                    found = True
        return found
