class BoyerMoore:
    def __init__(self, pattern):
        self.pattern = pattern
        self.m = len(pattern)
        self.bad_char = {}
        for i, c in enumerate(pattern):
            self.bad_char[c] = i
    def search(self, text):
        n = len(text)
        m = self.m
        res = []
        s = 0
        while s <= n - m:
            j = m - 1
            while j >= 0 and self.pattern[j] == text[s + j]:
                j -= 1
            if j < 0:
                res.append(s)
                s += (m - self.bad_char.get(text[s + m], -1)) if s + m < n else 1
            else:
                s += max(1, j - self.bad_char.get(text[s + j], -1))
        return res
