class BIT2D:
    def __init__(self, n, m):
        self.n, self.m = n, m
        self.tree = [[0]*(m+1) for _ in range(n+1)]
    def add(self, x, y, val):
        i = x
        while i <= self.n:
            j = y
            while j <= self.m:
                self.tree[i][j] += val
                j += j & -j
            i += i & -i
    def sum(self, x, y):
        res = 0
        i = x
        while i > 0:
            j = y
            while j > 0:
                res += self.tree[i][j]
                j -= j & -j
            i -= i & -i
        return res
    def range_sum(self, x1, y1, x2, y2):
        return self.sum(x2, y2) - self.sum(x1-1, y2) - self.sum(x2, y1-1) + self.sum(x1-1, y1-1)
