class RangeMinimumQuery:
    def __init__(self, arr):
        self.n = len(arr)
        self.block_size = max(1, int(self.n ** 0.5))
        self.blocks = []
        for i in range(0, self.n, self.block_size):
            self.blocks.append(min(arr[i:i+self.block_size]))
        self.arr = arr
    def query(self, l, r):
        ans = float('inf')
        while l <= r and l % self.block_size != 0:
            ans = min(ans, self.arr[l])
            l += 1
        while l + self.block_size - 1 <= r:
            ans = min(ans, self.blocks[l // self.block_size])
            l += self.block_size
        while l <= r:
            ans = min(ans, self.arr[l])
            l += 1
        return ans
