class ArticulationPoints:
    def __init__(self, n, adj):
        self.n = n
        self.adj = adj
        self.timer = 0
        self.visited = [False] * n
        self.tin = [-1] * n
        self.low = [-1] * n
        self.points = set()
        for v in range(n):
            if not self.visited[v]:
                self.dfs(v, -1)
    def dfs(self, v, p):
        self.visited[v] = True
        self.tin[v] = self.low[v] = self.timer
        self.timer += 1
        children = 0
        for to in self.adj[v]:
            if to == p:
                continue
            if self.visited[to]:
                self.low[v] = min(self.low[v], self.tin[to])
            else:
                self.dfs(to, v)
                self.low[v] = min(self.low[v], self.low[to])
                if self.low[to] >= self.tin[v] and p != -1:
                    self.points.add(v)
                children += 1
        if p == -1 and children > 1:
            self.points.add(v)
adj = [[1, 2], [0, 2], [0, 1, 3], [2, 4], [3]]
ap = ArticulationPoints(5, adj)
