class FourRussiansRMQ:
    def __init__(self, arr):
        self.arr = arr
        self.n = len(arr)
        self.block_size = max(1, (self.n.bit_length() + 1) // 2)
        self.num_blocks = (self.n + self.block_size - 1) // self.block_size
        self.block_mins = []
        for i in range(self.num_blocks):
            start = i * self.block_size
            end = min(self.n, start + self.block_size)
            self.block_mins.append(min(range(start, end), key=lambda x: arr[x]))
    def query(self, l, r):
        ans = l
        while l <= r and l % self.block_size != 0:
            if self.arr[l] < self.arr[ans]:
                ans = l
            l += 1
        while l + self.block_size <= r:
            idx = l // self.block_size
            if self.arr[self.block_mins[idx]] < self.arr[ans]:
                ans = self.block_mins[idx]
            l += self.block_size
        while l <= r:
            if self.arr[l] < self.arr[ans]:
                ans = l
            l += 1
        return ans
